<?php

namespace Tests\Support;

/**
 * Golden-file comparison of a workbook written by the application with the one the legacy platform wrote for the
 * same invented input (tests/fixtures/legacy, generated by running the legacy code once). The legacy brand, team and
 * company names were replaced there by « {app} », « {team} » and « {company} », filled in with this installation's
 * values.
 *
 * @phpstan-import-type SheetPicture from WorkbookSnapshot
 */
trait ComparesWithLegacyWorkbooks
{
    /**
     * @param  array<string, SheetPicture>  $actual
     * @param  array<string, string>  $placeholders
     * @param  (callable(array<string, SheetPicture>): array<string, SheetPicture>)|null  $deviations  Decided deviations from the legacy output, applied to the expected picture.
     */
    protected function assertSameAsLegacy(string $golden, array $actual, array $placeholders = [], ?callable $deviations = null): void
    {
        $this->assertSameAsLegacyFile(base_path('tests/fixtures/legacy/'.$golden), $actual, $placeholders, $deviations);
    }

    /**
     * @param  array<string, SheetPicture>  $actual
     * @param  array<string, string>  $placeholders
     * @param  (callable(array<string, SheetPicture>): array<string, SheetPicture>)|null  $deviations
     */
    protected function assertSameAsLegacyFile(string $path, array $actual, array $placeholders = [], ?callable $deviations = null): void
    {
        $golden = basename($path);
        $expected = WorkbookSnapshot::of($path);
        $expected = json_decode(strtr((string) json_encode($expected), array_map(fn (string $value) => trim((string) json_encode($value), '"'), $placeholders)), true);

        if ($deviations !== null) {
            $expected = $deviations($expected);
        }

        $expectedLines = array_map(self::typography(...), $this->lines($expected));
        $actualLines = array_map(self::typography(...), $this->lines($actual));
        $differences = [];

        foreach (array_unique([...array_keys($expectedLines), ...array_keys($actualLines)]) as $key) {
            if (($expectedLines[$key] ?? null) !== ($actualLines[$key] ?? null)) {
                $differences[] = "{$key}\n  - legacy: ".($expectedLines[$key] ?? '(nothing)')."\n  + app:    ".($actualLines[$key] ?? '(nothing)');
            }
        }

        if ($differences !== []) {
            $this->fail("The workbook differs from the legacy {$golden}:\n".implode("\n", $differences));
        }

        $this->assertSame($expectedLines, $actualLines);
    }

    /**
     * The French translations use the typographic apostrophe where the legacy texts had the straight one (decided:
     * the translation files follow French typography).
     */
    private static function typography(string $line): string
    {
        return str_replace('’', "'", $line);
    }

    /**
     * One line per sheet property and per cell, so that a failure lists what differs.
     *
     * @param  array<string, SheetPicture>  $snapshot
     * @return array<string, string>
     */
    private function lines(array $snapshot): array
    {
        $lines = ['sheets' => implode(' | ', array_keys($snapshot))];

        foreach ($snapshot as $title => $sheet) {
            foreach (['state', 'gridlines', 'merges', 'widths', 'heights'] as $key) {
                $lines["{$title} {$key}"] = (string) json_encode($sheet[$key], JSON_UNESCAPED_UNICODE);
            }

            foreach ($sheet['cells'] as $coordinate => $cell) {
                $lines["{$title}!{$coordinate}"] = (string) json_encode($cell, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
            }
        }

        return $lines;
    }
}
